/**
 * draw.io palette data pinned to jgraph/drawio v32.4.1: every sidebar palette (504) as one lazy
 * JSON chunk each, plus a catalogue (libraries, "More shapes" categories, counts) and a search
 * index (shards in data/search/), all lazy too. Generated by scripts/drawio-palettes/extract-palettes.ts.
 *
 * getBasenameForStencil is ported from jgraph/drawio v32.4.1
 * src/main/webapp/js/grapheditor/Graph.js:22346 (mxStencilRegistry.getBasenameForStencil).
 * Copyright (c) 2006-2025, JGraph Holdings Ltd / draw.io AG. Licensed under Apache-2.0.
 */
import type { DrawioPaletteId, PaletteCatalogue, PaletteDef, PaletteMeta, PaletteSearchIndex } from './types';

export type {
  CatalogueLibrary,
  CataloguePalette,
  DrawioPaletteId,
  PaletteCatalogue,
  PaletteDef,
  PaletteEntry,
  PaletteEntryClass,
  PaletteMeta,
  PaletteSearchIndex,
} from './types';

export const DRAWIO_TAG = 'v32.4.1';

/** Palettes in draw.io sidebar order; the legacy stencil-based Arrows palette is hidden by default. */
export const PALETTES: readonly PaletteMeta[] = [
  { id: 'general', title: 'General', defaultVisible: true },
  { id: 'misc', title: 'Misc', defaultVisible: true },
  { id: 'advanced', title: 'Advanced', defaultVisible: true },
  { id: 'basic', title: 'Basic', defaultVisible: true },
  { id: 'arrows2', title: 'Arrows', defaultVisible: true },
  { id: 'flowchart', title: 'Flowchart', defaultVisible: true },
  { id: 'arrows', title: 'Arrows (legacy)', defaultVisible: false },
];

/**
 * Stencil files (basenames under public/stencils/, without .xml) each palette needs, i.e.
 * getBasenameForStencil() of every stencil-rendered (cls 'b') shape name in the palette.
 * Kept static so callers can preload before the palette JSON is loaded; the unit test
 * checks it against the generated data.
 */
const STENCIL_BASENAMES: Record<DrawioPaletteId, readonly string[]> = {
  general: [],
  misc: [],
  advanced: [],
  basic: ['basic'],
  arrows2: [],
  flowchart: ['flowchart'],
  arrows: ['arrows'],
};

const LOADERS: Record<DrawioPaletteId, () => Promise<{ default: unknown }>> = {
  general: () => import('./data/general.json'),
  misc: () => import('./data/misc.json'),
  advanced: () => import('./data/advanced.json'),
  basic: () => import('./data/basic.json'),
  arrows2: () => import('./data/arrows2.json'),
  flowchart: () => import('./data/flowchart.json'),
  arrows: () => import('./data/arrows.json'),
};

export function isDrawioPaletteId(id: string): id is DrawioPaletteId {
  return Object.prototype.hasOwnProperty.call(LOADERS, id);
}

const cache = new Map<string, Promise<PaletteDef>>();

/**
 * File name (without .json) of a palette's data: the id itself when it is a plain identifier,
 * else `p-<slug>` (same rule as scripts/drawio-palettes/extract-palettes.ts paletteFileName).
 */
export function paletteFileName(id: string): string {
  if (/^[A-Za-z0-9_-]+$/.test(id)) return id;
  const s = id.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return 'p-' + (s || 'entry');
}

/** True when a generated palette with this id exists (any of the 504 draw.io palettes). */
export async function hasPalette(id: string): Promise<boolean> {
  if (isDrawioPaletteId(id)) return true;
  const { paletteDataLoader } = await import('./all-data');
  return paletteDataLoader(paletteFileName(id)) != null;
}

/** Loads a palette's data (code-split JSON chunk). Rejects for unknown ids. */
export function loadPalette(id: string): Promise<PaletteDef> {
  let p = cache.get(id);
  if (!p) {
    // the 504-entry chunk map lives in its own lazy module (it would add ~50 kB to the main chunk)
    const loader = isDrawioPaletteId(id)
      ? LOADERS[id]
      : () => import('./all-data').then(({ paletteDataLoader }) => {
          const load = paletteDataLoader(paletteFileName(id));
          if (!load) throw new Error(`Unknown draw.io palette: ${id}`);
          return load();
        });
    p = loader().then((m) => m.default as PaletteDef);
    p.catch(() => cache.delete(id));
    cache.set(id, p);
  }
  return p;
}

let cataloguePromise: Promise<PaletteCatalogue> | null = null;
/** The generated catalogue (libraries, palettes, "More shapes" categories); one lazy chunk. */
export function loadPaletteCatalogue(): Promise<PaletteCatalogue> {
  if (!cataloguePromise) {
    cataloguePromise = import('./data/catalogue.json').then((m) => (m as unknown as { default: PaletteCatalogue }).default);
    cataloguePromise.catch(() => { cataloguePromise = null; });
  }
  return cataloguePromise;
}

/** The search index shards (scripts/drawio-palettes/search-shards.ts), one ~200 kB lazy chunk each. */
const SEARCH_SHARDS = import.meta.glob<{ default: PaletteSearchIndex }>('./data/search/search-index-*.json');

let searchPromise: Promise<PaletteSearchIndex> | null = null;
/**
 * Titles and tags of every palette entry (`title\ttags`, entry order). Loaded on the first search:
 * every shard in parallel, concatenated in file-name order (= the catalogue order of the palettes).
 */
export function loadPaletteSearchIndex(): Promise<PaletteSearchIndex> {
  if (!searchPromise) {
    const files = Object.keys(SEARCH_SHARDS).sort();
    searchPromise = Promise.all(files.map((f) => SEARCH_SHARDS[f]())).then((mods) => {
      const shards = mods.map((m) => m.default);
      if (shards.length === 0) throw new Error('draw.io search index is missing');
      return { drawioTag: shards[0].drawioTag, palettes: shards.flatMap((s) => s.palettes) };
    });
    searchPromise.catch(() => { searchPromise = null; });
  }
  return searchPromise;
}

/** Stencil basenames to preload (e.g. ['basic'] -> `${BASE_URL}stencils/basic.xml`) before rendering the palette. */
export function paletteStencilBasenames(id: string): string[] {
  return isDrawioPaletteId(id) ? [...STENCIL_BASENAMES[id]] : [];
}

/**
 * mxStencilRegistry.getBasenameForStencil: 'mxgraph.mscae.enterprise.x' -> 'mscae/enterprise',
 * 'mxgraph.basic.x' -> 'basic'; null when the name is not an mxgraph.* stencil.
 * draw.io loads `stencils/<basename with '_-_' replaced by '_'>.xml` for it.
 */
export function getBasenameForStencil(name: string | null | undefined): string | null {
  let tmp: string | null = null;
  if (name != null && typeof name === 'string') {
    const parts = name.split('.');
    if (parts.length > 0 && parts[0] === 'mxgraph') {
      tmp = parts[1];
      for (let i = 2; i < parts.length - 1; i++) tmp += '/' + parts[i];
    }
  }
  return tmp ?? null;
}

/** Unique stencil file basenames (with draw.io's '_-_' -> '_' rule applied) for the given shape names. */
export function stencilBasenamesForShapes(shapeNames: Iterable<string>): string[] {
  const out: string[] = [];
  for (const name of shapeNames) {
    const b = getBasenameForStencil(name);
    if (b == null) continue;
    const file = b.replace('_-_', '_');
    if (!out.includes(file)) out.push(file);
  }
  return out;
}
